import { isMonitorRunning } from '../tasks/isMonitorRunning';
import { PerRunnerTasksWidget, useRunnerMonitor } from './widgets/PerRunnerTasksWidget';
import { EngineStatePill } from './EngineStatePill';
import { resolveMobileModelDetails } from './mobileModelDetails';
import { resolveMobileHeaderMode } from './mobileHeaderMode';
import { formatMobileMonitorTitle } from './mobileMonitorTitle';
import { resolveMobileModelLine } from './mobileModelLine';
import { LiveConsoleWidget } from './widgets/LiveConsoleWidget';

// Re-exported so older importers of the header formatters keep working after
// the move to single-purpose modules next to this view.
export { formatMobileMonitorTitle, resolveMobileModelLine };

/***
 * MARK: MobileMonitorView
 * @description Compact logs-only monitor: a two-row compressed status
 *   header above the full live log console. Shown automatically on
 *   phone-narrow viewports and on desktop when the user explicitly requests
 *   it (right-click the header Monitor button). Row 1 carries Back, the
 *   active chip, and — only when no Runner fleet is configured — the
 *   legacy global engine pill; with runners shown the per-runner rows are
 *   the status signal (mirroring `NowPlayingBar` fleet mode) and the chip
 *   names the task plus its stage (`<task> · <stage>`). Row 2 is a single
 *   truncated model-details line (full text in the tooltip), mirroring
 *   ActiveTaskPromptWidget on the main monitor view. Reuses
 *   LiveConsoleWidget directly — no forked console implementation — and
 *   stays within 360px with no horizontal scroll (truncation,
 *   min-width-zero flex children).
 * @param {Object} props
 * @param {Object|null} [props.engineState] - Engine snapshot (status, activeStageName); null renders the idle fallback.
 * @param {Object|null} [props.activeTask] - Resolved active task (title, goal, model, harness).
 * @param {Array<Object>|null} [props.stages] - Pipeline stages for the active task; null resolves no stage name.
 * @param {boolean} [props.isAgentRunning] - Agent running flag (running fallback).
 * @param {Array<Object>|null} [props.runnerTasks] - Tasks for the per-runner rows (titles resolve by id); null shows "details unavailable".
 * @param {Array<Object>|null} [props.runnerStages] - Stages for the per-runner rows (stage names resolve by id); null shows raw stage ids.
 * @param {Object} [props.stats] - Deprecated, ignored: kept so older callers passing task stats keep rendering.
 * @param {number} [props.queueCount] - Deprecated, ignored: kept so older callers passing queue length keep rendering.
 * @param {boolean} [props.schedulerRunning] - False renders STOPPED instead of IDLE.
 * @param {Array|null} [props.processLogs] - Log lines for the console; null shows the waiting-for-stream empty state.
 * @param {Function} [props.onClearLogs] - Clears the console.
 * @param {Function} [props.onExit] - Leaves the monitor (Back button).
 * @param {Array<Object>} [props.runnerAssignmentsOverride] - Injected live fleet assignments (tests); skips polling while set.
 * @param {Map|Array} [props.runnerRegistryOverride] - Injected Runner registry (tests); skips polling while set.
 * @example <MobileMonitorView engineState={engineState} activeTask={activeTask} processLogs={logs} onExit={...} />
 ***/
export function MobileMonitorView({
  engineState = {},
  activeTask = null,
  stages = [],
  isAgentRunning = false,
  runnerTasks = [],
  runnerStages = [],
  // Deprecated, ignored: retained for backwards compatibility with callers
  // that still pass task stats / queue length (see JSDoc above).
  stats: _stats = {},
  queueCount: _queueCount = 0,
  schedulerRunning,
  processLogs = [],
  onClearLogs,
  onExit = () => {},
  runnerAssignmentsOverride,
  runnerRegistryOverride,
}) {
  void _stats;
  void _queueCount;
  const engineStatus = engineState?.status || (isAgentRunning ? 'running' : 'idle');
  const isRunning = isMonitorRunning(engineState, isAgentRunning);
  const isCheckpoint = engineStatus === 'checkpoint' || engineStatus === 'waiting_human';
  const isPaused = engineStatus === 'paused';
  const details = resolveMobileModelDetails(activeTask, engineState);
  // Single fleet poller for the header + the compact runner rows (the rows
  // reuse the same state via overrides so one tick issues one fleet read).
  // Until the first read lands the fleet looks empty, so the pill renders
  // and then drops away once fleet presence is known: status is never
  // hidden on an unknown fleet, at the cost of one quick swap on load.
  const skipFleetPoll =
    runnerAssignmentsOverride !== undefined || runnerRegistryOverride !== undefined;
  const fleet = useRunnerMonitor({ enabled: !skipFleetPoll });
  const fleetAssignments =
    runnerAssignmentsOverride !== undefined ? runnerAssignmentsOverride : fleet.assignments;
  const fleetRegistry =
    runnerRegistryOverride !== undefined ? runnerRegistryOverride : fleet.registry;
  const headerMode = resolveMobileHeaderMode({
    assignments: fleetAssignments,
    registry: fleetRegistry,
    activeTask,
    stages,
    engineState,
  });
  // Pill-on (no fleet): legacy split — pill names the stage, title the task.
  // Pill-off (fleet shown): one named chip, `<task> · <stage>`, so the stage
  // still appears exactly once in the header.
  const activeChipLabel = !headerMode.showEnginePill && headerMode.activeChip
    ? headerMode.activeChip.label
    : formatMobileMonitorTitle(activeTask, engineState, isRunning);
  const modelLine = resolveMobileModelLine(details);

  return (
    <div
      data-testid="mobile-monitor-view"
      className="flex-1 flex flex-col min-h-0 h-full min-w-0 bg-[#0b0f17] text-slate-100 font-sans select-none overflow-hidden"
    >
      {/* Compressed status header: Back + named chip (+ engine pill only with no fleet) + one model line */}
      <header className="px-2 py-1.5 bg-[#0f172a] border-b border-slate-800/80 shrink-0 shadow-md">
        <div className="flex items-center gap-2 min-w-0">
          <button
            type="button"
            onClick={onExit}
            aria-label="Back to orchestrator"
            title="Back to orchestrator"
            className="px-2 py-0.5 min-h-[44px] rounded bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 hover:border-emerald-500 text-xs font-mono font-bold transition-colors cursor-pointer shrink-0"
          >
            ← Back
          </button>
          <span className="text-base shrink-0" aria-hidden="true">
            📡
          </span>
          {headerMode.showEnginePill && (
            <div className="min-w-0 shrink">
              <EngineStatePill
                engineState={engineState}
                activeTask={activeTask}
                stages={stages}
                isRunning={isRunning}
                isCheckpoint={isCheckpoint}
                isPaused={isPaused}
                schedulerRunning={schedulerRunning}
                testId="mobile-engine-state"
              />
            </div>
          )}
          <p
            data-testid="mobile-active-stage"
            title={activeChipLabel}
            className="flex-1 min-w-0 truncate text-xs font-mono text-slate-300 text-right"
            {...(headerMode.showEnginePill
              ? {}
              : { role: 'status', 'aria-live': 'polite' })}
          >
            {activeChipLabel}
          </p>
        </div>

        <div
          data-testid="mobile-monitor-model-details"
          title={modelLine?.title}
          className="mt-1 max-w-full truncate whitespace-nowrap text-[11px] font-mono text-slate-300"
        >
          {modelLine ? modelLine.line : 'Idle — no active model'}
        </div>
      </header>

      {/* Per-runner compact rows: who runs what, for how long */}
      <div className="shrink-0 max-h-40 overflow-y-auto border-b border-slate-800/80 px-2 py-1">
        <PerRunnerTasksWidget
          tasks={runnerTasks}
          stages={runnerStages}
          compact
          assignmentsOverride={fleetAssignments}
          registryOverride={fleetRegistry}
        />
      </div>

      {/* Full-height live log console (filters, auto-scroll, clear intact) */}
      <div className="flex-1 flex flex-col min-h-0 min-w-0 w-full">
        <LiveConsoleWidget processLogs={processLogs} onClearLogs={onClearLogs} />
      </div>
    </div>
  );
}

export default MobileMonitorView;

import { formatTaskTitleFirstLine } from '../tasks/taskFormatters';
import { resolveDisplayedStage } from '../tasks/runningTask';

/***
 * MARK: resolveMobileHeaderMode
 * @description Pure header-mode contract for the compact mobile monitor: the
 *   legacy single-threaded global pill (`ACTIVE/CHECKPOINT/PAUSED/IDLE`) is
 *   the only status signal when no Runner fleet is configured, and is
 *   dropped whenever fleet presence (a live assignment or a registered
 *   Runner) is shown — the per-runner rows already name each Runner's live
 *   state, mirroring `NowPlayingBar` fleet mode. The active chip names the
 *   task plus the stage it is on (`<task> · <stage>`, task first) so the
 *   unnamed `ACTIVE: <stage>` pill never leaves the task anonymous. Fails
 *   safe: unknown registry shapes count as no fleet (the pill stays
 *   visible — status is never hidden on bad input), and a malformed stage
 *   name falls back to the task-only chip instead of crashing the header.
 *   The contract is deliberately two fields: whether the pill fallback
 *   shows, and the named chip. Fleet presence is exactly the negation of
 *   the pill, so it is kept as a local (not returned) — the view already
 *   knows the fleet from its single poller.
 * @param {Object|null} [options] - Header inputs (null fails safe to the pill fallback).
 * @param {Array<Object>} [options.assignments] - Live fleet assignments (runnerId-bearing).
 * @param {Map|Array|number|null} [options.registry] - Runner registry (Map, list, or count).
 * @param {Object|null} [options.activeTask] - Resolved active task (title, goal, currentStageId).
 * @param {Array<Object>} [options.stages] - Pipeline stages for the active task.
 * @param {Object} [options.engineState] - Engine snapshot (status, activeStageName).
 * @returns {{showEnginePill: boolean, activeChip: {taskName: string, stageName: string|null, label: string}|null}} Header mode: pill fallback, and the named chip (null when no task names it).
 * @example resolveMobileHeaderMode({ assignments: [{ runnerId: 'r1' }], activeTask: { title: 'Build auth' } }).showEnginePill // false
 * @example resolveMobileHeaderMode(null).showEnginePill // true
 ***/
export function resolveMobileHeaderMode(options = {}) {
  // A null options bag must fail safe like a missing one: destructuring
  // `null` directly would throw and crash the header on bad input.
  const {
    assignments = [],
    registry = null,
    activeTask = null,
    stages = [],
    engineState = {},
  } = options ?? {};
  const liveFleetAssignments = (Array.isArray(assignments) ? assignments : []).filter(
    (assignment) => assignment && assignment.runnerId,
  );
  let registryCount = 0;
  if (registry instanceof Map) {
    registryCount = registry.size;
  } else if (Array.isArray(registry)) {
    registryCount = registry.filter((runner) => runner && runner.runnerId).length;
  } else if (typeof registry === 'number' && Number.isInteger(registry) && registry > 0) {
    // Only a positive whole count names a fleet: zero, negatives, and
    // fractions are malformed input, so the pill stays visible (fail-safe).
    registryCount = registry;
  }
  const fleetPresent = liveFleetAssignments.length > 0 || registryCount > 0;
  const showEnginePill = !fleetPresent;
  const taskName = formatTaskTitleFirstLine(
    activeTask?.title || activeTask?.goal || '',
    '',
  ).trim();
  // Stage names are display text, but a numeric id can leak through from a
  // malformed payload — the pill renders those, so the chip does too. Only
  // genuine non-text (objects, booleans) falls back to the task-only chip.
  const rawStageName = resolveDisplayedStage(
    activeTask,
    Array.isArray(stages) ? stages : [],
    engineState ?? {},
  )?.name;
  const stageName =
    typeof rawStageName === 'string'
      ? rawStageName.trim()
      : typeof rawStageName === 'number' && Number.isFinite(rawStageName)
        ? String(rawStageName)
        : '';
  const activeChip = taskName
    ? { taskName, stageName: stageName || null, label: stageName ? `${taskName} · ${stageName}` : taskName }
    : null;
  return { showEnginePill, activeChip };
}

/***
 * MARK: default resolveMobileHeaderMode
 * @description Default-export alias for `resolveMobileHeaderMode` so the
 *   compact monitor can import the header-mode contract either way.
 * @example resolveMobileHeaderMode({ assignments: [{ runnerId: 'r1' }] }).showEnginePill // false
 ***/
export default resolveMobileHeaderMode;
// Run in the lighter node environment: pure header-mode contract, no DOM needs.
// @vitest-environment node
import { expect, test, describe } from 'vitest';
import { resolveMobileHeaderMode } from './mobileHeaderMode';

const STAGES = [{ id: '5', name: 'Catchup', type: 'agent' }];
const TASK = { id: 't1', title: 'Build user auth', currentStageId: '5' };

describe('resolveMobileHeaderMode', () => {
  test('runners live + running: pill off, chip names task + stage', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'local-alpha', taskId: 't1' }],
      registry: new Map([['local-alpha', {}]]),
      activeTask: TASK,
      stages: STAGES,
      engineState: { status: 'running', activeStageName: 'Build' },
    });
    expect(mode.showEnginePill).toBe(false);
    expect(mode.activeChip).toEqual({
      taskName: 'Build user auth',
      stageName: 'Catchup',
      label: 'Build user auth · Catchup',
    });
  });

  test('fleet registered but between assignments: pill stays off (fleet-idle rows state)', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [],
      registry: new Map([['local-alpha', {}]]),
      activeTask: TASK,
      stages: STAGES,
      engineState: { status: 'idle' },
    });
    expect(mode.showEnginePill).toBe(false);
  });

  test('no runners configured: pill on, legacy single-task display preserved', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [],
      registry: new Map(),
      activeTask: TASK,
      stages: STAGES,
      engineState: { status: 'running', activeStageName: 'Build' },
    });
    expect(mode.showEnginePill).toBe(true);
    expect(mode.activeChip?.label).toBe('Build user auth · Catchup');
  });

  test('checkpoint/paused with runners shown: pill off, per-runner state is the signal', () => {
    for (const status of ['checkpoint', 'waiting_human', 'paused']) {
      const mode = resolveMobileHeaderMode({
        assignments: [{ runnerId: 'local-alpha', taskId: 't1' }],
        registry: [],
        activeTask: TASK,
        stages: STAGES,
        engineState: { status },
      });
      expect(mode.showEnginePill).toBe(false);
    }
  });

  test('idle with no runners: pill on and chip falls back with no task', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [],
      registry: [],
      activeTask: null,
      stages: [],
      engineState: {},
    });
    expect(mode.showEnginePill).toBe(true);
    expect(mode.activeChip).toBeNull();
  });

  test('chip is null without a task name; stage alone never invents one', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'r1' }],
      activeTask: null,
      stages: [],
      engineState: { status: 'running', activeStageName: 'Build' },
    });
    expect(mode.activeChip).toBeNull();
    expect(mode.showEnginePill).toBe(false);
  });

  test('registry accepts a list or a count, not just a Map', () => {
    expect(
      resolveMobileHeaderMode({ assignments: [], registry: [{ runnerId: 'r1' }] })
        .showEnginePill,
    ).toBe(false);
    expect(resolveMobileHeaderMode({ assignments: [], registry: 2 }).showEnginePill).toBe(
      false,
    );
    expect(resolveMobileHeaderMode({ assignments: [], registry: 0 }).showEnginePill).toBe(
      true,
    );
  });

  test('chip falls back to the goal first line when the task has no title', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'r1' }],
      activeTask: { id: 't2', goal: '# Ship the widget\nSecond line' },
      stages: [],
      engineState: {},
    });
    expect(mode.activeChip?.taskName).toBe('Ship the widget');
    expect(mode.activeChip?.label).toBe('Ship the widget');
  });

  test('assignments without a runnerId never count as fleet presence', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ taskId: 't1' }, null],
      registry: [],
      activeTask: TASK,
      stages: STAGES,
      engineState: { status: 'running' },
    });
    expect(mode.showEnginePill).toBe(true);
  });

  test('missing inputs fail safe to the pill fallback, never a crash', () => {
    expect(resolveMobileHeaderMode()).toEqual({
      showEnginePill: true,
      activeChip: null,
    });
    expect(resolveMobileHeaderMode(null)).toEqual({
      showEnginePill: true,
      activeChip: null,
    });
    const nulls = resolveMobileHeaderMode({
      assignments: null,
      registry: null,
      activeTask: null,
      stages: null,
      engineState: null,
    });
    expect(nulls.showEnginePill).toBe(true);
    expect(nulls.activeChip).toBeNull();
  });

  test('unknown registry shapes and counts count as no fleet (pill stays visible)', () => {
    for (const registry of ['local-alpha', { size: 5 }, -1, 0.5, 2.5, NaN, Infinity]) {
      const mode = resolveMobileHeaderMode({ assignments: [], registry });
      expect(mode.showEnginePill).toBe(true);
    }
  });

  test('a wrong-type active task never crashes the resolver and names no chip', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'r1' }],
      registry: [],
      activeTask: 'not-a-task',
      stages: STAGES,
      engineState: { status: 'running', activeStageName: 'Build' },
    });
    expect(mode.activeChip).toBeNull();
    expect(mode.showEnginePill).toBe(false);
  });

  test('non-array assignments and stages never crash the resolver', () => {
    const mode = resolveMobileHeaderMode({
      assignments: 'local-alpha',
      registry: [],
      activeTask: TASK,
      stages: 'Catchup',
      engineState: { status: 'running' },
    });
    expect(mode.showEnginePill).toBe(true);
    expect(mode.activeChip?.taskName).toBe('Build user auth');
  });

  test('a numeric stage name still renders, like the pill does', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'r1' }],
      activeTask: TASK,
      stages: [{ id: '5', name: 7, type: 'agent' }],
      engineState: {},
    });
    expect(mode.activeChip).toEqual({
      taskName: 'Build user auth',
      stageName: '7',
      label: 'Build user auth · 7',
    });
  });

  test('a non-text stage name falls back to the task-only chip', () => {
    const mode = resolveMobileHeaderMode({
      assignments: [{ runnerId: 'r1' }],
      activeTask: TASK,
      stages: [{ id: '5', name: { text: 'Catchup' }, type: 'agent' }],
      engineState: {},
    });
    expect(mode.activeChip).toEqual({
      taskName: 'Build user auth',
      stageName: null,
      label: 'Build user auth',
    });
  });
});

