import { formatModelRef } from '../../services/formatModelRef';
import { isAutomatedStage } from '../stageTypes';

/***
 * MARK: resolveMobileModelDetails
 * @description Pure resolver for the mobile monitor header's model details
 *   row. Mirrors the pill logic of ActiveTaskPromptWidget (the main monitor
 *   view's authoritative model display) so the two can never drift apart:
 *   fully scripted stages (`ci`/`deploy`/`merge`) show an `Automated — no
 *   model` pill instead of harness/model; harness-managed stages
 *   (`modelSelection: "none"`) show only the Harness pill; agent stages show
 *   Harness + Model pills with a Provider/Source sub-line when known. A
 *   missing `modelSelection` means `"list"`. The backend `isAutomatedStage`
 *   flag wins when present; the local stage-type predicate covers older
 *   backends. Unknown stage types stay fail-visible (pills shown). With no
 *   active task the row renders the idle fallback instead of blanking.
 * @param {Object|null} [activeTask] - Resolved active task (model, harness, modelDetails, modelSelection, stageType).
 * @param {Object} [engineState] - Engine snapshot (activeStageType fallback).
 * @returns {{model: {harness: string|null, provider: string|null, id: string|null, label: string}, modelRef: string|null, harness: string, provider: string|null, source: string|null, modelSelection: string, stageType: string|undefined, isScripted: boolean, isIdle: boolean, showHarness: boolean, showModel: boolean, showProviderLine: boolean, showAlias: boolean, aliasName: string|null, aliasMissing: string|null, aliasTitle: string|undefined}}
 * @example resolveMobileModelDetails({ model: 'pi::pi::qwen3:8b', harness: 'pi' }, {}).showModel // true
 ***/
export function resolveMobileModelDetails(activeTask = null, engineState = {}) {
  const hasTask =
    !!activeTask &&
    (typeof activeTask !== 'object' || Object.keys(activeTask).length > 0);
  const modelRef = activeTask?.modelDetails?.key || activeTask?.model || null;
  const model = formatModelRef(modelRef);
  const harness = activeTask?.harness || model.harness || 'Unknown';
  const provider = activeTask?.modelDetails?.provider || model.provider || null;
  const source = activeTask?.modelDetails?.source || null;
  const modelSelection = activeTask?.modelSelection || 'list';
  const stageType =
    activeTask?.stageType || activeTask?.currentStageType || engineState?.activeStageType;
  // Scripted stages run no model: the backend flag is authoritative when
  // present; the local predicate covers older backends without the flag.
  const isScripted =
    typeof activeTask?.isAutomatedStage === 'boolean'
      ? activeTask.isAutomatedStage
      : isAutomatedStage(stageType);
  const isIdle = !hasTask;
  const showHarness = !isScripted && !isIdle;
  const showModel = !isScripted && !isIdle && modelSelection !== 'none';
  const showProviderLine = showModel && (!!provider || !!source);
  // The alias behind the run (resolved) or the unresolvable ref (missing);
  // both hide on scripted stages and stay absent on old payloads.
  const aliasName = activeTask?.alias?.name || null;
  const aliasMissing = !aliasName ? activeTask?.aliasMissing || null : null;
  const showAlias = !isScripted && !isIdle && !!(aliasName || aliasMissing);
  const aliasTitle =
    aliasName && typeof activeTask?.alias?.targetIndex === 'number'
      ? `alias ${aliasName}, target ${activeTask.alias.targetIndex + 1}`
      : undefined;

  return {
    model,
    modelRef,
    harness,
    provider,
    source,
    modelSelection,
    stageType,
    isScripted,
    isIdle,
    showHarness,
    showModel,
    showProviderLine,
    showAlias,
    aliasName,
    aliasMissing,
    aliasTitle,
  };
}

export default resolveMobileModelDetails;
===== mobileModelLine.js =====
/***
 * MARK: resolveMobileModelLine
 * @description Compresses the header's model details into one truncated
 *   line (`alias · Harness · Model · Provider/Source`, full text in the
 *   `title` tooltip) so the compact header stays at two rows on 360px
 *   viewports. Presentation only: the resolver semantics
 *   (`resolveMobileModelDetails`, mirroring ActiveTaskPromptWidget) are
 *   reused untouched. Missing or idle details render the idle fallback;
 *   scripted stages keep the `Automated — no model` wording. Fails safe:
 *   nullish details return null (the view renders its fallback line), and
 *   any missing label renders as `Unknown` — a half-shaped payload can
 *   never crash the header or print `undefined`.
 * @param {Object|null} [details] - The resolved model details (nullish renders the idle fallback).
 * @returns {{line: string, title: string}|null} Single-line text plus tooltip, or null for the idle fallback.
 * @example resolveMobileModelLine({ showHarness: true, harness: 'pi', showModel: true, model: { label: 'qwen3:8b' }, modelRef: 'pi::pi::qwen3:8b' }).line // 'Harness: pi · Model: qwen3:8b'
 * @example resolveMobileModelLine(null) // null
 ***/
export function resolveMobileModelLine(details) {
  if (details == null || details.isIdle) return null;
  if (details.isScripted) return { line: 'Automated — no model', title: 'Automated — no model' };
  const parts = [];
  const titleParts = [];
  if (details.showAlias) {
    const aliasName =
      details.aliasName ||
      (details.aliasMissing ? `${details.aliasMissing} (unresolved)` : 'Unknown');
    const alias = `alias: ${aliasName}`;
    parts.push(alias);
    titleParts.push(details.aliasTitle ? `${alias} (${details.aliasTitle})` : alias);
  }
  if (details.showHarness) {
    const harness = `Harness: ${details.harness || 'Unknown'}`;
    parts.push(harness);
    titleParts.push(harness);
  }
  if (details.showModel) {
    // The line truncates to the short label; the tooltip keeps the full ref
    // so a long model identifier is never lost at 360px.
    const modelLabel = details.model?.label || details.modelRef || 'Unknown';
    parts.push(`Model: ${modelLabel}`);
    titleParts.push(`Model: ${details.modelRef || modelLabel}`);
  }
  if (details.showProviderLine) {
    const provider = `Provider: ${details.provider || 'Unknown'} · Source: ${details.source || 'unknown'}`;
    parts.push(provider);
    titleParts.push(provider);
  }
  const line = parts.join(' · ') || 'Idle — no active model';
  return { line, title: titleParts.join(' · ') || line };
}

/***
 * MARK: default resolveMobileModelLine
 * @description Default-export alias for `resolveMobileModelLine` so the
 *   compact monitor model-line formatter can be imported either way.
 * @example resolveMobileModelLine({ showHarness: true, harness: 'pi' }).line // 'Harness: pi'
 ***/
export default resolveMobileModelLine;
===== mobileMonitorTitle.js =====
import { formatTaskTitleFirstLine } from '../tasks/taskFormatters';

/***
 * MARK: formatMobileMonitorTitle
 * @description Pure formatter for the compact monitor header's right-side
 *   text when no Runner fleet is shown. The engine pill already shows the
 *   stage name when running, so this text shows the active task identity
 *   instead (title, falling back to the goal's first line with a leading
 *   markdown heading stripped — mirroring ActiveTaskPromptWidget). When a
 *   fleet is shown the view uses the header-mode chip (`<task> · <stage>`)
 *   instead, falling back to this title only when no task names the chip.
 *   When idle with no task the previous stage/empty text is kept so the
 *   header never blanks.
 * @param {Object|null} [activeTask] - Resolved active task (title, goal).
 * @param {Object} [engineState] - Engine snapshot (activeStageName).
 * @param {boolean} [isRunning] - Engine currently executing.
 * @returns {string} Header text for the right-side element.
 * @example formatMobileMonitorTitle({ title: 'Build auth' }, {}, true) // 'Build auth'
 * @example formatMobileMonitorTitle(null, {}, false) // 'No active stage'
 ***/
export function formatMobileMonitorTitle(activeTask = null, engineState = {}, isRunning = false) {
  // First-line extraction shares the markdown-strip rule with every other
  // title surface; the idle fallback chain below stays local to this header.
  const taskName = formatTaskTitleFirstLine(activeTask?.title || activeTask?.goal || '', '').trim();
  if (taskName) return taskName;
  if (isRunning) return 'No active task';
  return engineState?.activeStageName || 'No active stage';
}

/***
 * MARK: default formatMobileMonitorTitle
 * @description Default-export alias for `formatMobileMonitorTitle` so the
 *   compact monitor title formatter can be imported either way.
 * @example formatMobileMonitorTitle({ title: 'Build auth' }, {}, true) // 'Build auth'
 ***/
export default formatMobileMonitorTitle;

