import { useCallback, useEffect, useState } from 'react';
import { api } from '../services/api';

/***
 * MARK: fleetCountsById
 * @description Indexes a fleet catalogue payload by model id for option
 *   badges: `{ [id]: { runnerCount, runnerIds, harnesses, tiers } }`.
 *   Malformed entries never crash a picker — they are skipped.
 * @example fleetCountsById({ models: [{ id: 'm', runnerCount: 2, runnerIds: ['r1', 'r2'] }] })
 *   => { m: { runnerCount: 2, runnerIds: ['r1', 'r2'], harnesses: [], tiers: [] } }
 * @param {Object} [payload] - `/runners/models/catalogue` response.
 * @returns {Object} Id-keyed availability map.
 ***/
export function fleetCountsById(payload) {
  const map = {};
  const list = Array.isArray(payload?.models) ? payload.models : [];
  for (const entry of list) {
    const id = typeof entry?.id === 'string' ? entry.id.trim() : '';
    if (!id || Object.hasOwn(map, id)) continue;
    map[id] = {
      runnerCount: typeof entry.runnerCount === 'number' ? entry.runnerCount : 0,
      runnerIds: Array.isArray(entry.runnerIds)
        ? entry.runnerIds.filter((r) => typeof r === 'string')
        : [],
      harnesses: Array.isArray(entry.harnesses)
        ? entry.harnesses.filter((h) => typeof h === 'string')
        : [],
      tiers: Array.isArray(entry.tiers)
        ? entry.tiers.filter((t) => typeof t === 'string')
        : [],
    };
  }
  return map;
}

/***
 * MARK: useFleetModelCatalog
 * @description Fetches the fleet model catalogue (derived live from Runner
 *   registrations) once on mount: per-model runner availability for the
 *   stage, default, and alias pickers. No client cache — the backend
 *   derives it per request, so joins, leaves, and allowlist edits reflect
 *   on the next mount or manual `refresh()`. Failures resolve to an empty
 *   map (pickers render badge-free, never mislead).
 * @example const { counts, loading, loaded, refresh } = useFleetModelCatalog();
 * @param {Object} [opts]
 * @param {boolean} [opts.enabled=true] - When false, no request until it flips true.
 * @returns {{counts: Object, loading: boolean, loaded: boolean, refresh: Function}}
 ***/
export function useFleetModelCatalog({ enabled = true } = {}) {
  const [counts, setCounts] = useState({});
  // True only after a catalogue fetch succeeds: pickers gate badges on this
  // (not on `counts` being non-empty) so a failed fetch — or a backend
  // without the endpoint — renders badge-free instead of "No runners".
  const [loaded, setLoaded] = useState(false);
  const [loading, setLoading] = useState(
    () => enabled && typeof api.getFleetModelCatalog === 'function',
  );

  useEffect(() => {
    if (!enabled || typeof api.getFleetModelCatalog !== 'function') {
      return undefined;
    }
    let isMounted = true;
    api
      .getFleetModelCatalog()
      .then((res) => {
        if (!isMounted) return;
        setCounts(fleetCountsById(res));
        setLoaded(true);
      })
      .catch(() => {
        if (isMounted) setCounts({});
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });
    return () => {
      isMounted = false;
    };
  }, [enabled]);

  const refresh = useCallback(async () => {
    if (typeof api.getFleetModelCatalog !== 'function') return;
    try {
      const res = await api.getFleetModelCatalog();
      setCounts(fleetCountsById(res));
      setLoaded(true);
    } catch {
      // Keep the current map; a refresh failure never downgrades `loaded`.
    }
  }, []);

  return { counts, loading, loaded, refresh };
}

import { RUNNER_PROTOCOL } from "../runnerRegistry.js";
import { runnerApiCompatible } from "./runnerApiCompat.js";
import { operatorConfigVerdict } from "./operatorConfigVerdict.js";
import { stageRunnerPolicyVerdict } from "../../../shared/stageRunnerPolicy.js";

/***
 * MARK: effectiveRunnerModels
 * @description The model ids one Runner may serve: the operator-owned
 *   `availableModels` allowlist when set (System Settings › Runners ›
 *   Models — it replaces the advertised list so an under-reporting Runner
 *   can serve declared models), otherwise the Runner-advertised
 *   capabilities list. Single enforcement point shared by the dispatch
 *   gate below and the fleet model catalogue, so the two can never drift.
 * @example effectiveRunnerModels({ capabilities: { models: ['m1'] } }) => ['m1']
 * @param {Object} [record={}] - Runner record.
 * @returns {string[]} Effective model ids (possibly empty).
 ***/
export function effectiveRunnerModels(record = {}) {
	const override = record?.operatorConfig?.availableModels;
	if (Array.isArray(override)) return override;
	const caps = record?.capabilities && typeof record.capabilities === "object" ? record.capabilities : {};
	return Array.isArray(caps.models) ? caps.models : [];
}

/***
 * MARK: claimEligibleRunner
 * @description Whether one Runner registration can take ANY work right now:
 *   active status and not paused — the same two gates `runnerMatches`
 *   applies before per-task requirements. The fleet model catalogue counts
 *   only eligible Runners, so "available on N runners" always names
 *   Runners that could actually claim.
 * @example claimEligibleRunner({ status: 'active', paused: false }) => true
 * @param {Object} [record={}] - Runner record.
 * @returns {boolean} Eligibility.
 ***/
export function claimEligibleRunner(record = {}) {
	return record?.status === "active" && record?.paused !== true;
}

/***
 * MARK: runnerMatches
 * @description Decides whether one Runner registration can take a task with
 *   the given requirements: active status, not paused, fresh heartbeat
 *   (staleness expiry), v1 protocol, runnable flag, harness id, model
 *   offering, tier membership, and disk headroom floor. Returns
 *   `{ ok, reason }` — the
 *   reason code is loud by design (step-6 NO_CAPABLE_RUNNER diagnostics
 *   and the monitor surface distinguish "no runners" from "runners that
 *   cannot take this job"). Alias requirements always miss here; WP-3.2
 *   resolves them centrally first. The last two gates are owner settings:
 *   the Runner's own `operatorConfig` first, then the stage's
 *   `runnerPolicy` (`RUNNER_NOT_ALLOWED` / `RUNNER_BLOCKED`) — owner
 *   settings keep a stable order so combined refusals always report the
 *   same reason.
 * @example runnerMatches(record, { harness: 'pi', tier: 'T1' }) => { ok: true, reason: 'MATCH' }
 * @param {Object} record - Registry record (`status`, `facts`, `lastSeenAt`, `capabilities`, plus the operator-owned `operatorConfig` the Runners settings screen persists).
 * @param {Object} req - Task requirements from `taskRequirements`.
 * @param {Object} [opts] - `{ now, staleAfterMs, minDiskHeadroomMb, projectId }` (`projectId` is the candidate's project, needed for the operator project-scope check; a scoped Runner with no project id on the candidate misses loudly instead of guessing).
 * @returns {Object} `{ ok, reason }`.
 ***/
export function runnerMatches(record = {}, req = {}, opts = {}) {
	const now = typeof opts.now === "number" ? opts.now : Date.now();
	const staleAfterMs =
		typeof opts.staleAfterMs === "number" && opts.staleAfterMs > 0
			? opts.staleAfterMs
			: 60000;
	const minDisk =
		typeof opts.minDiskHeadroomMb === "number" && opts.minDiskHeadroomMb >= 0
			? opts.minDiskHeadroomMb
			: 100;
	if (record.status !== "active") return { ok: false, reason: "NOT_ACTIVE" };
	if (record.paused === true) return { ok: false, reason: "PAUSED" };
	const seen = Date.parse(record.lastSeenAt || "");
	if (!Number.isFinite(seen) || now - seen > staleAfterMs) {
		return { ok: false, reason: "STALE_HEARTBEAT" };
	}
	const caps = record.capabilities || {};
	if (caps.runnable === false) return { ok: false, reason: "NOT_RUNNABLE" };
	const protocol =
		caps.versions?.protocol || record.facts?.versions?.protocol;
	if (protocol !== RUNNER_PROTOCOL) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	const runnerApi = caps.versions?.api || record.facts?.versions?.api;
	if (!runnerApiCompatible(runnerApi).ok) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	// Only the raw string marker (taskRequirements' `{ alias: name }`) is
	// unservable here. A resolved alias object (`{ name, targetIndex }`,
	// stamped by the route after central D3 resolution) carries the
	// concrete harness/model below and matches like any direct requirement.
	if (typeof req.alias === "string" && req.alias) {
		return { ok: false, reason: "ALIAS_UNRESOLVED" };
	}
	if (req.harness) {
		const offered = Array.isArray(caps.harnesses) ? caps.harnesses : [];
		if (!offered.some((h) => h && h.id === req.harness)) {
			return { ok: false, reason: "NO_HARNESS" };
		}
	}
	if (req.model) {
		if (!effectiveRunnerModels(record).includes(req.model))
			return { ok: false, reason: "NO_MODEL" };
	}
	if (req.tier) {
		const tiers = Array.isArray(caps.tiers) ? caps.tiers : [];
		if (!tiers.includes(req.tier)) return { ok: false, reason: "TIER_CEILING" };
	}
	if (caps.diskHeadroomMb !== null && caps.diskHeadroomMb !== undefined) {
		if (caps.diskHeadroomMb < minDisk) return { ok: false, reason: "DISK_LOW" };
	}
	// Operator-owned configuration (System Settings › Runners) refines an
	// otherwise-capable match without touching Runner-reported facts. It
	// sits after every health/capability gate so those keep their stable
	// reasons (a stale Runner still reports STALE_HEARTBEAT, never a scope
	// miss). The verdict itself lives in `operatorConfigVerdict`, shared
	// with the direct claim and integration lease routes so no claim path
	// can bypass the operator's settings.
	const operatorVerdict = operatorConfigVerdict(record, req, opts);
	if (!operatorVerdict.ok) return operatorVerdict;
	// Stage runnerPolicy (the stage settings allow/block list) is the final
	// gate: after the operator's own settings, so a Runner refused by both
	// always reports the operator reason, and after every health/capability
	// gate so those keep their stable reasons too.
	const policyVerdict = stageRunnerPolicyVerdict(req.runnerPolicy, record.runnerId);
	if (!policyVerdict.ok) return policyVerdict;
	return { ok: true, reason: "MATCH" };
}

#!/usr/bin/env node
/***
 * MARK: check-one-function-per-file
 * @description New-file shape gate (WP-8, binding q1/q2/q3/q13): every source
 *   file outside the grandfather allowlist must declare at most ONE top-level
 *   named function. Only `function name` declarations at brace depth 0 count
 *   (nested declarations, callbacks, and arrow-function constants are ignored
 *   per q1). Files that already held >= 2 top-level named functions when the
 *   gate landed are listed in `scripts/allowlists/one-function-per-file.json`
 *   and keep passing untouched (q13); an allowlisted path that is itself
 *   newly added still fails so the list cannot grandfather brand-new code.
 * @example node scripts/check-one-function-per-file.mjs (exit 0 on a clean tree)
 * @example node scripts/check-one-function-per-file.mjs --write-allowlist
 * @example node scripts/check-one-function-per-file.mjs --report
 ***/

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(HERE, "..");
export const ALLOWLIST_PATH = path.join(
	REPO_ROOT,
	"scripts",
	"allowlists",
	"one-function-per-file.json",
);

const ROOTS = ["api", "shared", path.join("frontend", "src")];
const SOURCE_EXTS = new Set([".js", ".jsx"]);
const SKIP_BASENAMES = new Set(["node_modules", "dist", ".git", "coverage"]);

/***
 * MARK: isSourceFile
 * @description Whether a repo-relative POSIX path is in the gate's scope:
 *   a .js/.jsx file under api/, shared/, or frontend/src/, excluding
 *   test/spec files, node_modules, and build output.
 * @example isSourceFile("api/work/taskErrors.js") => true
 * @param {string} relPath - Repo-relative POSIX path.
 * @returns {boolean} True when the file is checked by this gate.
 ***/
export function isSourceFile(relPath) {
	const ext = path.posix.extname(relPath);
	if (!SOURCE_EXTS.has(ext)) return false;
	if (!ROOTS.some((root) => relPath === root || relPath.startsWith(`${root}/`)))
		return false;
	const base = path.posix.basename(relPath);
	if (base.includes(".test.") || base.includes(".spec.")) return false;
	if (relPath.split("/").some((part) => SKIP_BASENAMES.has(part))) return false;
	return true;
}

/***
 * MARK: stripNonCode
 * @description Masks comments and string/template literals with spaces (keeping
 *   newlines and length stable) so keyword scans never match prose, URLs, or
 *   doc examples. Handles line/block comments, single/double quotes, and
 *   template literals with `${}` interpolation.
 * @example stripNonCode("const s = 'function x';") hides the quoted words
 * @param {string} source - Raw file text.
 * @returns {string} Masked text of identical length.
 ***/
export function stripNonCode(source) {
	const out = source.split("");
	const len = source.length;
	const mask = (from, to) => {
		for (let k = from; k < to; k++) {
			if (out[k] !== "\n") out[k] = " ";
		}
	};
	const skipString = (i) => {
		const quote = source[i];
		let j = i + 1;
		while (j < len) {
			if (source[j] === "\\") j += 2;
			else if (source[j] === quote) {
				j++;
				break;
			} else j++;
		}
		mask(i, j);
		return j;
	};
	// Skips `${ ... }` starting at the `$`, honouring nested strings,
	// comments, templates, and braces. Returns the index after the `}`.
	const skipInterpolation = (i) => {
		let j = i + 2;
		let depth = 1;
		while (j < len && depth > 0) {
			const ch = source[j];
			const next = source[j + 1];
			if (ch === "/" && next === "/") {
				let k = j + 2;
				while (k < len && source[k] !== "\n") k++;
				mask(j, k);
				j = k;
			} else if (ch === "/" && next === "*") {
				const end = source.indexOf("*/", j + 2);
				const k = end === -1 ? len : end + 2;
				mask(j, k);
				j = k;
			} else if (ch === "'" || ch === '"') {
				j = skipString(j);
			} else if (ch === "`") {
				j = skipTemplate(j);
			} else {
				if (ch === "{") depth++;
				else if (ch === "}") depth--;
				j++;
			}
		}
		return j;
	};
	// Masks a template literal starting at the backtick, scanning
	// `${}` interpolations as code. Returns the index after the closing
	// backtick (or end of input for an unterminated literal).
	const skipTemplate = (i) => {
		let j = i + 1;
		let segStart = j;
		while (j < len) {
			const ch = source[j];
			if (ch === "\\") j += 2;
			else if (ch === "`") {
				mask(segStart, j);
				mask(j, j + 1);
				return j + 1;
			} else if (ch === "$" && source[j + 1] === "{") {
				mask(segStart, j);
				j = skipInterpolation(j);
				segStart = j;
			} else j++;
		}
		if (segStart < len) mask(segStart, len);
		return len;
	};
	let i = 0;
	while (i < len) {
		const ch = source[i];
		const next = source[i + 1];
		if (ch === "/" && next === "/") {
			let j = i + 2;
			while (j < len && source[j] !== "\n") j++;
			mask(i, j);
			i = j;
		} else if (ch === "/" && next === "*") {
			const end = source.indexOf("*/", i + 2);
			const j = end === -1 ? len : end + 2;
			mask(i, j);
			i = j;
		} else if (ch === "'" || ch === '"') {
			i = skipString(i);
		} else if (ch === "`") {
			i = skipTemplate(i);
		} else {
			i++;
		}
	}
	return out.join("");
}

/***
 * MARK: topLevelFunctions
 * @description Lists top-level named `function` declarations in a source file:
 *   `function foo`, `async function foo`, `export function foo`,
 *   `export default function foo` (anonymous defaults are ignored — there is
 *   no name to split into its own file). Nested declarations sit at brace
 *   depth > 0 and are ignored per q1, as are arrow-function constants (no
 *   `function` keyword).
 * @example topLevelFunctions("export function a() {}\nfunction b() {}") => ["a", "b"]
 * @param {string} source - Raw file text.
 * @returns {Array<string>} Declared names in source order.
 ***/
export function topLevelFunctions(source) {
	const masked = stripNonCode(source);
	const names = [];
	const len = masked.length;
	let depth = 0;
	const isIdChar = (c) => /[$\w]/.test(c);
	let i = 0;
	while (i < len) {
		const ch = masked[i];
		if (ch === "{" || ch === "}") {
			depth += ch === "{" ? 1 : -1;
			if (depth < 0) depth = 0;
			i++;
			continue;
		}
		if (
			ch === "f" &&
			masked.startsWith("function", i) &&
			!isIdChar(masked[i - 1] || "") &&
			!isIdChar(masked[i + 8] || "")
		) {
			let j = i + 8;
			while (j < len && /\s/.test(masked[j])) j++;
			if (masked[j] === "*") {
				j++;
				while (j < len && /\s/.test(masked[j])) j++;
			}
			let name = "";
			while (j < len && isIdChar(masked[j])) {
				name += masked[j];
				j++;
			}
			if (depth === 0 && name) names.push(name);
			i = j;
			continue;
		}
		i++;
	}
	return names;
}

/***
 * MARK: collectSourceFiles
 * @description Walks the gate's roots and returns every in-scope source file
 *   as a repo-relative POSIX path, sorted.
 * @example collectSourceFiles().every(isSourceFile) => true
 * @returns {Array<string>} Sorted repo-relative POSIX paths.
 ***/
export function collectSourceFiles() {
	const found = [];
	const walk = (dir) => {
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			if (entry.name.startsWith(".") || SKIP_BASENAMES.has(entry.name)) continue;
			const full = path.join(dir, entry.name);
			if (entry.isDirectory()) walk(full);
			else if (entry.isFile()) {
				const rel = path.relative(REPO_ROOT, full).split(path.sep).join("/");
				if (isSourceFile(rel)) found.push(rel);
			}
		}
	};
	for (const root of ROOTS) {
		const abs = path.join(REPO_ROOT, root);
		if (fs.existsSync(abs)) walk(abs);
	}
	return found.sort();
}

/***
 * MARK: readAllowlist
 * @description Reads the committed grandfather allowlist (empty when absent —
 *   a missing file means "no grandfathered files", never a crash).
 * @example readAllowlist() returns an array of repo-relative paths
 * @returns {Array<string>} Sorted allowlisted repo-relative POSIX paths.
 ***/
export function readAllowlist() {
	try {
		const raw = JSON.parse(fs.readFileSync(ALLOWLIST_PATH, "utf8"));
		return Array.isArray(raw) ? [...raw].sort() : [];
	} catch {
		return [];
	}
}

/***
 * MARK: resolveDiffBase
 * @description Resolves the merge-base ancestor for newly-added detection
 *   (origin/master, origin/main, master, main — first that resolves), or null
 *   outside a git checkout / with no known default branch.
 * @example resolveDiffBase() => "abc123..." or null
 * @returns {string|null} A commit-ish, or null when git cannot answer.
 ***/
export function resolveDiffBase() {
	try {
		for (const ref of ["origin/master", "origin/main", "master", "main"]) {
			try {
				execFileSync("git", ["rev-parse", "--verify", ref], {
					cwd: REPO_ROOT,
					stdio: ["ignore", "pipe", "ignore"],
				});
				return ref;
			} catch {
				// Try the next candidate.
			}
		}
		return null;
	} catch {
		return null;
	}
}

/***
 * MARK: listNewlyAdded
 * @description Repo-relative POSIX paths that are newly added: committed as
 *   Added vs the diff base, or untracked (`??`) in the working tree. An
 *   allowlisted path that is newly added still fails — the allowlist is for
 *   files that existed before the gate (q13), not a way to grandfather
 *   brand-new code. Degrades to [] when git is unavailable.
 * @example listNewlyAdded().every((p) => typeof p === "string") => true
 * @returns {Array<string>} Newly-added repo-relative POSIX paths.
 ***/
export function listNewlyAdded() {
	try {
		const added = new Set();
		const base = resolveDiffBase();
		if (base) {
			const out = execFileSync(
				"git",
				["diff", "--name-status", "--diff-filter=A", `${base}...HEAD`],
				{ cwd: REPO_ROOT, encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] },
			);
			for (const line of out.split("\n")) {
				const file = line.replace(/^[AMDRCTUX]+\s+/, "").trim();
				if (file) added.add(file);
			}
		}
		const status = execFileSync("git", ["status", "--porcelain"], {
			cwd: REPO_ROOT,
			encoding: "utf8",
			stdio: ["ignore", "pipe", "ignore"],
		});
		for (const line of status.split("\n")) {
			if (line.startsWith("??")) {
				const file = line.slice(2).trim().replace(/"/g, "");
				if (file) added.add(file.endsWith("/") ? file : file);
			}
		}
		return [...added].sort();
	} catch {
		return [];
	}
}

/***
 * MARK: checkFiles
 * @description Pure gate core: for each file's declared top-level functions,
 *   fails paths with >= 2 names unless allowlisted AND not newly added.
 * @example checkFiles({ "a.js": ["f", "g"] }, [], []) fails a.js
 * @param {Object<string, Array<string>>} counts - File -> declared names.
 * @param {Array<string>} allowlist - Grandfathered paths.
 * @param {Array<string>} newlyAdded - Newly-added paths (still fail).
 * @returns {{ failures: Array<Object>, stale: Array<string> }} Failures and allowlist entries no longer needed.
 ***/
export function checkFiles(counts, allowlist, newlyAdded) {
	const allowed = new Set(allowlist);
	const added = new Set(newlyAdded);
	const failures = [];
	for (const [file, names] of Object.entries(counts)) {
		if (names.length < 2) continue;
		if (allowed.has(file) && !added.has(file)) continue;
		failures.push({ file, names, grandfatheredButNew: allowed.has(file) });
	}
	const stale = allowlist.filter((file) => (counts[file] || []).length < 2);
	return { failures, stale };
}

/***
 * MARK: formatFailure
 * @description Renders the remediation-forward gate failure (plan §4.4/§7:
 *   gate name, offending locations, why, remediation, local repro).
 * @example formatFailure([{ file: "a.js", names: ["f", "g"] }]) mentions one-function-per-file
 * @param {Array<Object>} failures - Failing files with declared names.
 * @returns {string} Human-readable failure text.
 ***/
export function formatFailure(failures) {
	const lines = ["FAIL: new-file shape (one-function-per-file)", ""];
	for (const { file, names, grandfatheredButNew } of failures) {
		lines.push(`${file} — ${names.length} top-level named functions:`);
		names.forEach((name, i) => lines.push(`  ${i + 1}. ${name}`));
		if (grandfatheredButNew) {
			lines.push("  (this path is allowlisted, but it is newly added: the");
			lines.push("  allowlist only covers files that existed before the gate.)");
		}
		lines.push("");
	}
	lines.push("Newly added source files must declare at most one top-level named function.");
	lines.push("");
	lines.push("Remediation:");
	lines.push("  1. Split each function into its own file named after the function");
	lines.push("     (e.g. api/work/buildFoo.js for function buildFoo).");
	lines.push("  2. Keep this file as a barrel re-export if callers need one entry point.");
	lines.push("  3. Do NOT add this file to scripts/allowlists/one-function-per-file.json:");
	lines.push("     that list is reserved for files that existed before this gate (q13).");
	lines.push("See: AGENTS-MAP.md §one-function-per-file, KB Code Standards §modularity.");
	lines.push("");
	lines.push("Reproduce locally: npm run check:one-function");
	return lines.join("\n");
}

function scanCounts() {
	const counts = {};
	for (const file of collectSourceFiles()) {
		const source = fs.readFileSync(path.join(REPO_ROOT, file), "utf8");
		counts[file] = topLevelFunctions(source);
	}
	return counts;
}

const invokedDirectly =
	process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) {
	const args = new Set(process.argv.slice(2));
	if (args.has("--write-allowlist")) {
		const counts = scanCounts();
		const listed = Object.entries(counts)
			.filter(([, names]) => names.length >= 2)
			.map(([file]) => file)
			.sort();
		fs.mkdirSync(path.dirname(ALLOWLIST_PATH), { recursive: true });
		fs.writeFileSync(ALLOWLIST_PATH, `${JSON.stringify(listed, null, 2)}\n`);
		console.log(`allowlist: wrote ${listed.length} files to ${path.relative(REPO_ROOT, ALLOWLIST_PATH)}`);
	} else {
		const counts = scanCounts();
		const allowlist = readAllowlist();
		const newlyAdded = listNewlyAdded();
		if (args.has("--report")) {
			const multi = Object.entries(counts).filter(([, names]) => names.length >= 2);
			console.log(`one-function-per-file report: ${multi.length} multi-function files`);
			for (const [file, names] of multi) {
				const tag = allowlist.includes(file) ? "allowlisted" : "UNLISTED";
				console.log(`  ${tag} ${file} (${names.length}): ${names.join(", ")}`);
			}
			const { stale } = checkFiles(counts, allowlist, newlyAdded);
			if (stale.length > 0) {
				console.log(`stale allowlist entries (now <= 1 function, may prune): ${stale.join(", ")}`);
			}
		}
		const { failures } = checkFiles(counts, allowlist, newlyAdded);
		if (failures.length > 0) {
			console.error(formatFailure(failures));
			process.exit(1);
		}
		console.log(
			`one-function-per-file: PASS (${Object.keys(counts).length} files scanned, ${allowlist.length} grandfathered)`,
		);
	}
}

